tool_schemas.implementation:
def Optional_Settings(action, user_id=None, session_id=None, server_id=None, server_access_id=None, access_token=None, refresh_token=None, email=None, password=None, auth_provider=None, display_name=None, status=None, server=None, access_grant=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, secrets, base64, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0292000" if __import__("os").path.isdir("./environment_mix/0292000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str):
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _crockford32(nbytes=16):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        b = secrets.token_bytes(nbytes)
        num = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            out.append(alphabet[num & 31])
            num >>= 5
        return "".join(reversed(out))

    def _gen_id(prefix):
        return f"{prefix}{_crockford32(16)}"

    def _is_nonempty_str(x):
        return isinstance(x, str) and bool(x.strip())

    _RE_USER = re.compile(r"^inb_usr_[0-9A-HJKMNP-TV-Z]{16,}$")
    _RE_SESS = re.compile(r"^inb_sess_[0-9A-HJKMNP-TV-Z]{16,}$")
    _RE_SRV = re.compile(r"^inb_srv_[0-9A-HJKMNP-TV-Z]{16,}$")
    _RE_SACC = re.compile(r"^inb_sacc_[0-9A-HJKMNP-TV-Z]{16,}$")
    _RE_EMAIL = re.compile(r"^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9-]+(\.[a-z0-9-]+)+$")

    def _valid_url(u):
        if not _is_nonempty_str(u):
            return False
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _find_usage_file():
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return "request_logs.json"

    def _log(endpoint, http_status, credential, error_code=None, meta=None):
        fname = _find_usage_file()
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": f"inb_req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "credential": credential,
            "status": http_status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now()),
        }
        if isinstance(meta, dict):
            row.update({"meta": meta})
        rows.append(row)
        _save(fname, rows)
        return row, fname, rows

    def _rate_limit_check(credential):
        # Sliding window: 120 req/min per credential; if no credential, 60 req/min shared.
        fname = _find_usage_file()
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        now = _now()
        window_s = 60
        limit = 120 if credential else 60
        cutoff = now - datetime.timedelta(seconds=window_s)

        def _row_time(r):
            ts = r.get("timestamp")
            dt = _parse_dt(ts) if isinstance(ts, str) else None
            return dt

        cnt = 0
        for r in rows:
            if r.get("credential") != credential:
                continue
            dt = _row_time(r)
            if dt is None:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, {"limit": limit, "window_seconds": window_s, "used": cnt}
        return True, {"limit": limit, "window_seconds": window_s, "used": cnt}

    def _authenticate_session_by_access_token(access_token_raw):
        # IMPORTANT: access_token in this system is already a client-visible token string;
        # sessions store access_token_hash. The vendor convention in this dataset is that the
        # raw token begins with "sha256$<hex>" or could be the session id.
        sessions = _load("sessions.json")
        users = _load("users.json")
        if not isinstance(sessions, list):
            sessions = []
        if not isinstance(users, list):
            users = []

        if not _is_nonempty_str(access_token_raw):
            return None, None, "VALIDATION_ERROR", "access_token must be a non-empty string"

        token = access_token_raw.strip()

        candidates = []
        # 1) If token matches a session id, allow it (client-visible value).
        if _RE_SESS.match(token):
            candidates = [s for s in sessions if s.get("id") == token]
        else:
            # 2) If token is already "sha256$<hex>", use that hex as the hash.
            if token.startswith("sha256$") and re.fullmatch(r"sha256\$[0-9a-fA-F]{64}", token):
                h = token.split("$", 1)[1].lower()
                candidates = [s for s in sessions if isinstance(s.get("access_token_hash"), str) and s.get("access_token_hash").lower() == h]
            else:
                # 3) Otherwise hash it.
                h = _sha256_hex(token)
                candidates = [s for s in sessions if isinstance(s.get("access_token_hash"), str) and s.get("access_token_hash").lower() == h]

        if not candidates:
            return None, None, "UNAUTHORIZED", "Invalid, revoked, or expired session"

        now = _now()
        # pick a working active, unexpired session
        for sess in candidates:
            exp = _parse_dt(sess.get("expires_at"))
            if sess.get("status") == "active" and exp and exp > now:
                uid = sess.get("user_id")
                user = next((u for u in users if u.get("id") == uid), None)
                if not user:
                    continue
                if user.get("status") != "active":
                    # User not active cannot authenticate; treat as unauthorized.
                    continue
                return user, sess, None, None

        return None, None, "UNAUTHORIZED", "Invalid, revoked, or expired session"

    def _public_context_fallback():
        # When no access_token is provided by the tool, resolve an ambient authenticated context.
        # Choose any active, unexpired session whose user is active.
        sessions = _load("sessions.json")
        users = _load("users.json")
        if not isinstance(sessions, list):
            sessions = []
        if not isinstance(users, list):
            users = []
        now = _now()
        for sess in sessions:
            exp = _parse_dt(sess.get("expires_at"))
            if sess.get("status") != "active" or not exp or exp <= now:
                continue
            uid = sess.get("user_id")
            user = next((u for u in users if u.get("id") == uid and u.get("status") == "active"), None)
            if user:
                return user, sess
        return None, None

    def _sanitize_user(u):
        if not isinstance(u, dict):
            return u
        out = dict(u)
        if "password_hash" in out:
            out.pop("password_hash", None)
        return out

    def _sort_rows(rows, key, desc=False):
        def _k(r):
            v = r.get(key)
            if key.endswith("_at") or key in ("issued_at", "expires_at", "last_login_at"):
                dt = _parse_dt(v) if isinstance(v, str) else (v if isinstance(v, datetime.datetime) else None)
                return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if isinstance(v, str):
                return v.lower()
            return v
        return sorted(rows, key=_k, reverse=desc)

    def _cursor_pack(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _cursor_unpack(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Validate action
    allowed_actions = {
        "sign_up", "sign_in", "sign_out", "refresh_session",
        "get_current_user", "update_user",
        "list_servers", "create_server", "get_server", "update_server", "delete_server",
        "list_server_access", "grant_server_access", "revoke_server_access",
        "list_sessions", "revoke_session",
    }
    if action not in allowed_actions:
        _log("Optional Settings", 400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid action", field="action", allowed=sorted(allowed_actions))

    # Rate-limit before doing work (uses credential if present)
    cred_for_rl = access_token if _is_nonempty_str(access_token) else None
    ok_rl, rl_meta = _rate_limit_check(cred_for_rl)
    if not ok_rl:
        _log("Optional Settings", 429, cred_for_rl, "RATE_LIMIT", meta={"rate_limit": rl_meta})
        return _err("RATE_LIMIT", "Rate limit exceeded", rate_limit=rl_meta)

    # Helper: require auth unless action explicitly allows none
    def _require_auth():
        if _is_nonempty_str(access_token):
            u, s, ecode, emsg = _authenticate_session_by_access_token(access_token)
            if ecode:
                return None, None, _err(ecode, emsg)
            return u, s, None
        # No credential param: derive ambient context if possible
        u, s = _public_context_fallback()
        if not u or not s:
            return None, None, _err("UNAUTHORIZED", "Unauthenticated: active session required")
        return u, s, None

    def _has_server_role(uid, sid, roles):
        sacc = _load("server_access.json")
        if not isinstance(sacc, list):
            sacc = []
        for g in sacc:
            if g.get("server_id") == sid and g.get("user_id") == uid and g.get("status") == "active" and g.get("role") in roles:
                return g
        return None

    def _server_exists_and_not_deleted(sid):
        srvs = _load("servers.json")
        if not isinstance(srvs, list):
            srvs = []
        srv = next((x for x in srvs if x.get("id") == sid), None)
        if not srv:
            return None, None
        return srv, srvs

    # Implement actions
    try:
        if action == "sign_up":
            # Create user (or idempotently return existing by email) and create a session
            users = _load("users.json")
            sessions = _load("sessions.json")
            if not isinstance(users, list):
                users = []
            if not isinstance(sessions, list):
                sessions = []

            if not _is_nonempty_str(email) or not _RE_EMAIL.match(email.strip().lower()):
                _log("Optional Settings", 400, cred_for_rl, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid email", field="email")
            eml = email.strip().lower()

            ap = auth_provider or "local"
            if ap not in ("local", "google_oauth", "github_oauth", "saml", "oidc"):
                _log("Optional Settings", 400, cred_for_rl, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid auth_provider", field="auth_provider")

            if ap == "local" and not _is_nonempty_str(password):
                _log("Optional Settings", 400, cred_for_rl, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "password is required for local auth", field="password")

            existing = next((u for u in users if isinstance(u.get("email"), str) and u.get("email").lower() == eml), None)
            now = _now()
            if existing:
                # Cannot authenticate deleted/disabled user
                if existing.get("status") != "active":
                    _log("Optional Settings", 403, cred_for_rl, "UNAUTHORIZED")
                    return _err("UNAUTHORIZED", "User is not active")
                # Issue new session
                ttl_s = 3600
                token_hash = None
                for _ in range(10):
                    raw = "sha256$" + _sha256_hex(secrets.token_urlsafe(32))
                    h = raw.split("$", 1)[1].lower()
                    if not any(isinstance(s.get("access_token_hash"), str) and s.get("access_token_hash").lower() == h for s in sessions):
                        token_hash = h
                        access_token_out = raw
                        break
                if not token_hash:
                    _log("Optional Settings", 409, cred_for_rl, "CONFLICT")
                    return _err("CONFLICT", "Could not allocate unique access token")

                sess = {
                    "id": _gen_id("inb_sess_"),
                    "user_id": existing["id"],
                    "access_token_hash": token_hash,
                    "refresh_token_hash": None,
                    "status": "active",
                    "issued_at": _iso(now),
                    "expires_at": _iso(now + datetime.timedelta(seconds=ttl_s)),
                    "last_seen_at": None,
                    "ip_address": None,
                    "user_agent": None,
                    "created_at": _iso(now),
                    "updated_at": _iso(now),
                }
                sessions.append(sess)
                existing["last_login_at"] = _iso(now)
                existing["updated_at"] = _iso(now)
                _save("sessions.json", sessions)
                _save("users.json", users)
                _log("Optional Settings", 200, access_token_out, None, meta={"rate_limit": rl_meta})
                return {
                    "action": action,
                    "user": _sanitize_user(existing),
                    "session": {k: v for k, v in sess.items() if k not in ("access_token_hash", "refresh_token_hash")},
                    "access_token": access_token_out,
                    "rate_limit": rl_meta,
                }

            # Create new user
            uid = _gen_id("inb_usr_")
            # Since we don't have raw password verification here, accept provided "password" as already a hash if it looks like one.
            pw_hash = None
            if ap == "local":
                pw_hash = password.strip()
                if not _is_nonempty_str(pw_hash):
                    _log("Optional Settings", 400, cred_for_rl, "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "password must be provided for local auth", field="password")

            user_row = {
                "id": uid,
                "email": eml,
                "display_name": display_name if isinstance(display_name, str) else None,
                "password_hash": pw_hash,
                "auth_provider": ap,
                "status": "active",
                "last_login_at": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }

            # transactional unique(email)
            if any(isinstance(u.get("email"), str) and u.get("email").lower() == eml for u in users):
                _log("Optional Settings", 409, cred_for_rl, "CONFLICT")
                return _err("CONFLICT", "Email already exists", field="email")

            users.append(user_row)

            # Issue session
            ttl_s = 3600
            token_hash = None
            access_token_out = None
            for _ in range(10):
                raw = "sha256$" + _sha256_hex(secrets.token_urlsafe(32))
                h = raw.split("$", 1)[1].lower()
                if not any(isinstance(s.get("access_token_hash"), str) and s.get("access_token_hash").lower() == h for s in sessions):
                    token_hash = h
                    access_token_out = raw
                    break
            if not token_hash:
                _log("Optional Settings", 409, cred_for_rl, "CONFLICT")
                return _err("CONFLICT", "Could not allocate unique access token")

            sess = {
                "id": _gen_id("inb_sess_"),
                "user_id": uid,
                "access_token_hash": token_hash,
                "refresh_token_hash": None,
                "status": "active",
                "issued_at": _iso(now),
                "expires_at": _iso(now + datetime.timedelta(seconds=ttl_s)),
                "last_seen_at": None,
                "ip_address": None,
                "user_agent": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            sessions.append(sess)
            user_row["last_login_at"] = _iso(now)
            user_row["updated_at"] = _iso(now)

            _save("users.json", users)
            _save("sessions.json", sessions)
            _log("Optional Settings", 201, access_token_out, None, meta={"rate_limit": rl_meta})
            return {
                "action": action,
                "user": _sanitize_user(user_row),
                "session": {k: v for k, v in sess.items() if k not in ("access_token_hash", "refresh_token_hash")},
                "access_token": access_token_out,
                "rate_limit": rl_meta,
            }

        if action == "sign_in":
            users = _load("users.json")
            sessions = _load("sessions.json")
            if not isinstance(users, list):
                users = []
            if not isinstance(sessions, list):
                sessions = []

            if not _is_nonempty_str(email) or not _RE_EMAIL.match(email.strip().lower()):
                _log("Optional Settings", 400, cred_for_rl, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid email", field="email")
            eml = email.strip().lower()
            u = next((x for x in users if isinstance(x.get("email"), str) and x.get("email").lower() == eml), None)
            if not u:
                _log("Optional Settings", 401, cred_for_rl, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Invalid credentials")

            if u.get("status") != "active":
                _log("Optional Settings", 403, cred_for_rl, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "User is not active")

            ap = auth_provider or u.get("auth_provider")
            if ap != u.get("auth_provider"):
                # allow caller to omit; but if provided and mismatched, reject
                _log("Optional Settings", 400, cred_for_rl, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "auth_provider does not match user", field="auth_provider")

            # We cannot verify argon2 hashes offline. Accept if provided password exactly equals stored password_hash
            # OR if password looks like an argon2 hash and stored is present (caller passed hash).
            if u.get("auth_provider") == "local":
                if not _is_nonempty_str(password):
                    _log("Optional Settings", 400, cred_for_rl, "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "password is required for local auth", field="password")
                stored = u.get("password_hash")
                if not (_is_nonempty_str(stored) and password.strip() == stored):
                    _log("Optional Settings", 401, cred_for_rl, "UNAUTHORIZED")
                    return _err("UNAUTHORIZED", "Invalid credentials")

            now = _now()
            ttl_s = 3600
            token_hash = None
            access_token_out = None
            for _ in range(10):
                raw = "sha256$" + _sha256_hex(secrets.token_urlsafe(32))
                h = raw.split("$", 1)[1].lower()
                if not any(isinstance(s.get("access_token_hash"), str) and s.get("access_token_hash").lower() == h for s in sessions):
                    token_hash = h
                    access_token_out = raw
                    break
            if not token_hash:
                _log("Optional Settings", 409, cred_for_rl, "CONFLICT")
                return _err("CONFLICT", "Could not allocate unique access token")

            sess = {
                "id": _gen_id("inb_sess_"),
                "user_id": u["id"],
                "access_token_hash": token_hash,
                "refresh_token_hash": None,
                "status": "active",
                "issued_at": _iso(now),
                "expires_at": _iso(now + datetime.timedelta(seconds=ttl_s)),
                "last_seen_at": _iso(now),
                "ip_address": None,
                "user_agent": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            sessions.append(sess)
            u["last_login_at"] = _iso(now)
            u["updated_at"] = _iso(now)
            _save("sessions.json", sessions)
            _save("users.json", users)
            _log("Optional Settings", 200, access_token_out, None, meta={"rate_limit": rl_meta})
            return {
                "action": action,
                "user": _sanitize_user(u),
                "session": {k: v for k, v in sess.items() if k not in ("access_token_hash", "refresh_token_hash")},
                "access_token": access_token_out,
                "rate_limit": rl_meta,
            }

        if action == "sign_out":
            u, sess, auth_err = _require_auth()
            if auth_err:
                _log("Optional Settings", 401, cred_for_rl, auth_err["error"]["code"])
                return auth_err

            sessions = _load("sessions.json")
            if not isinstance(sessions, list):
                sessions = []
            # find the stored row by id
            idx = next((i for i, s in enumerate(sessions) if s.get("id") == sess.get("id")), None)
            if idx is None:
                _log("Optional Settings", 404, access_token, "NOT_FOUND")
                return _err("NOT_FOUND", "Session not found")

            cur = sessions[idx]
            if cur.get("status") != "active":
                _log("Optional Settings", 409, access_token, "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Only active sessions can be revoked", from_status=cur.get("status"), to_status="revoked")

            now = _now()
            cur["status"] = "revoked"
            cur["updated_at"] = _iso(now)
            _save("sessions.json", sessions)
            _log("Optional Settings", 200, access_token, None, meta={"rate_limit": rl_meta})
            return {
                "action": action,
                "session": {k: v for k, v in cur.items() if k not in ("access_token_hash", "refresh_token_hash")},
                "rate_limit": rl_meta,
            }

        if action == "get_current_user":
            u, sess, auth_err = _require_auth()
            if auth_err:
                _log("Optional Settings", 401, cred_for_rl, auth_err["error"]["code"])
                return auth_err
            _log("Optional Settings", 200, access_token, None, meta={"rate_limit": rl_meta})
            return {"action": action, "user": _sanitize_user(u), "rate_limit": rl_meta}

        if action == "update_user":
            u, sess, auth_err = _require_auth()
            if auth_err:
                _log("Optional Settings", 401, cred_for_rl, auth_err["error"]["code"])
                return auth_err

            target_id = user_id or u.get("id")
            if not (_is_nonempty_str(target_id) and _RE_USER.match(target_id)):
                _log("Optional Settings", 400, access_token, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid user_id", field="user_id")

            # Only allow self-update (no admin model defined)
            if target_id != u.get("id"):
                _log("Optional Settings", 403, access_token, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Not permitted")

            users = _load("users.json")
            if not isinstance(users, list):
                users = []
            idx = next((i for i, r in enumerate(users) if r.get("id") == target_id), None)
            if idx is None:
                _log("Optional Settings", 404, access_token, "NOT_FOUND")
                return _err("NOT_FOUND", "User not found")

            now = _now()
            row = users[idx]
            if isinstance(display_name, str):
                row["display_name"] = display_name
            # status transitions via dedicated tools; ignore 'status' if present
            row["updated_at"] = _iso(now)
            users[idx] = row
            _save("users.json", users)
            _log("Optional Settings", 200, access_token, None, meta={"rate_limit": rl_meta})
            return {"action": action, "user": _sanitize_user(row), "rate_limit": rl_meta}

        if action == "list_servers":
            # unauthenticated: return only "public/default configuration (if any)" -> treat as none.
            authed_user = None
            authed_sess = None
            if _is_nonempty_str(access_token):
                authed_user, authed_sess, ecode, emsg = _authenticate_session_by_access_token(access_token)
                if ecode:
                    authed_user = None
