                return auth_err
            sessions = _load("sessions.json")
            if not isinstance(sessions, list):
                sessions = []
            idx = next((i for i, s in enumerate(sessions) if s.get("id") == sess.get("id")), None)
            if idx is None:
                _log("Optional Settings", 404, access_token, "NOT_FOUND")
                return _err("NOT_FOUND", "Session not found")

            now = _now()
            # rotate token hash uniquely
            token_hash = None
            access_token_out = None
            for _ in range(10):
                raw = "sha256$" + _sha256_hex(secrets.token_urlsafe(32))
                h = raw.split("$", 1)[1].lower()
                if not any(isinstance(s.get("access_token_hash"), str) and s.get("access_token_hash").lower() == h for s in sessions):
                    token_hash = h
                    access_token_out = raw
                    break
            if not token_hash:
                _log("Optional Settings", 409, access_token, "CONFLICT")
                return _err("CONFLICT", "Could not allocate unique access token")

            row = sessions[idx]
            if row.get("status") != "active":
                _log("Optional Settings", 409, access_token, "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Only active sessions can be refreshed", from_status=row.get("status"), to_status="active")
            row["access_token_hash"] = token_hash
            row["expires_at"] = _iso(now + datetime.timedelta(seconds=3600))
            row["updated_at"] = _iso(now)
            sessions[idx] = row
            _save("sessions.json", sessions)
            _log("Optional Settings", 200, access_token_out, None, meta={"rate_limit": rl_meta})
            return {"action": action, "session": {k: v for k, v in row.items() if k not in ("access_token_hash", "refresh_token_hash")}, "access_token": access_token_out, "rate_limit": rl_meta}

        _log("Optional Settings", 400, cred_for_rl, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Action not implemented")

    except Exception as e:
        # unexpected condition: return error object but do not mask programmer errors broadly; here we must not raise.
        _log("Optional Settings", 500, cred_for_rl, "CONFLICT")
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

def Optional_Settings__list_users(access_token, filters=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0292000" if __import__("os").path.isdir("./environment_mix/0292000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None
    def _parse_dt(x):
        if x is None: return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str): return None
        s = x.strip()
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _find_usage_file():
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return "request_logs.json"

    def _rate_meta(rows, credential):
        # Simple per-credential rate limit: 120/min
        limit_n = 120
        window_s = 60
        now = _now()
        used = 0
        for r in rows:
            if not isinstance(r, dict): 
                continue
            if r.get("credential") != credential:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                used += 1
        return {"limit": limit_n, "window_seconds": window_s, "used": used}

    def _log(http_status, credential, error_code=None, meta=None):
        fname = _find_usage_file()
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": f"inb_req_{int(time.time()*1000)}",
            "endpoint": "Optional Settings: list_users",
            "credential": credential,
            "status": http_status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now()),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        rows.append(row)
        _save(fname, rows)

    def _auth_session(access_token_raw):
        # IMPORTANT: authenticate against client-visible value OR id, not stored hash.
        sessions = _load("sessions.json")
        users = _load("users.json")
        if not isinstance(sessions, list): sessions = []
        if not isinstance(users, list): users = []
        now = _now()

        if not isinstance(access_token_raw, str) or not access_token_raw.strip():
            return None, None, "VALIDATION_ERROR", {"field": "access_token"}

        token = access_token_raw.strip()

        # Accept either session.id == token, or session.access_token_hash == token (client may pass pre-hashed token)
        candidates = []
        for s in sessions:
            if not isinstance(s, dict): 
                continue
            if s.get("id") == token or s.get("access_token_hash") == token:
                candidates.append(s)

        # If no direct match, also allow token to be raw, while store has sha256$... in access_token_hash.
        # We'll hash raw token and compare to stored access_token_hash only when it looks like stored format.
        if not candidates:
            h = hashlib.sha256(token.encode("utf-8")).hexdigest()
            alt = f"sha256${h}"
            for s in sessions:
                if not isinstance(s, dict): 
                    continue
                if s.get("access_token_hash") in (h, alt):
                    candidates.append(s)

        # Pick an actually active+unexpired session and active user
        for s in candidates:
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if not exp or exp <= now:
                continue
            uid = s.get("user_id")
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid), None)
            if not u:
                continue
            if u.get("status") != "active":
                continue
            return u, s, None, None
        return None, None, "UNAUTHORIZED", None

    # ---- Validate inputs
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        # log before returning
        _log(400, access_token, "VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "Invalid limit", field="limit")
    if limit < 1 or limit > 200:
        _log(400, access_token, "VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "-created_at", "email", "-email", "last_login_at", "-last_login_at"):
        _log(400, access_token, "VALIDATION_ERROR", {"field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log(400, access_token, "VALIDATION_ERROR", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    if filters is not None and not isinstance(filters, dict):
        _log(400, access_token, "VALIDATION_ERROR", {"field": "filters"})
        return _err("VALIDATION_ERROR", "Invalid filters", field="filters")

    allowed_auth = {"local", "google_oauth", "github_oauth", "saml", "oidc"}
    allowed_status = {"active", "disabled", "deleted"}
    if isinstance(filters, dict):
        for k in filters.keys():
            if k not in ("email", "auth_provider", "status"):
                _log(400, access_token, "VALIDATION_ERROR", {"field": "filters"})
                return _err("VALIDATION_ERROR", "Invalid filters property", field="filters")
        if "email" in filters:
            if not isinstance(filters["email"], str) or not filters["email"].strip():
                _log(400, access_token, "VALIDATION_ERROR", {"field": "filters.email"})
                return _err("VALIDATION_ERROR", "Invalid email filter", field="filters.email")
            email = filters["email"].strip()
            if email.lower() != email:
                _log(400, access_token, "VALIDATION_ERROR", {"field": "filters.email"})
                return _err("VALIDATION_ERROR", "email must be lowercase", field="filters.email")
            # RFC5322-like: pragmatic check
            if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email):
                _log(400, access_token, "VALIDATION_ERROR", {"field": "filters.email"})
                return _err("VALIDATION_ERROR", "Invalid email format", field="filters.email")
        if "auth_provider" in filters:
            if filters["auth_provider"] not in allowed_auth:
                _log(400, access_token, "VALIDATION_ERROR", {"field": "filters.auth_provider"})
                return _err("VALIDATION_ERROR", "Invalid auth_provider filter", field="filters.auth_provider")
        if "status" in filters:
            if filters["status"] not in allowed_status:
                _log(400, access_token, "VALIDATION_ERROR", {"field": "filters.status"})
                return _err("VALIDATION_ERROR", "Invalid status filter", field="filters.status")

    # ---- Authenticate
    user, sess, err_code, err_extra = _auth_session(access_token)
    if err_code:
        meta = None
        if err_code in ("UNAUTHORIZED",):
            # still provide rate limit meta when available
            fname = _find_usage_file()
            rows = _load(fname)
            if not isinstance(rows, list): rows = []
            meta = {"rate_limit": _rate_meta(rows, access_token)}
        _log(401, access_token, err_code, meta)
        if err_extra:
            return _err(err_code, "Invalid, revoked, or expired session" if err_code == "UNAUTHORIZED" else "Validation error", **err_extra)
        return _err(err_code, "Invalid, revoked, or expired session")

    # ---- Rate limit check (after auth)
    fname = _find_usage_file()
    rrows = _load(fname)
    if not isinstance(rrows, list): rrows = []
    rl = _rate_meta(rrows, access_token)
    if rl["used"] >= rl["limit"]:
        _log(429, access_token, "RATE_LIMIT", {"rate_limit": rl})
        return _err("RATE_LIMIT", "Rate limit exceeded", rate_limit=rl)

    # ---- List (no password hashes returned)
    users_rows = _load("users.json")
    if not isinstance(users_rows, list):
        users_rows = []

    def _matches(u):
        if not isinstance(u, dict): 
            return False
        if isinstance(filters, dict):
            if "email" in filters and u.get("email") != filters["email"].strip():
                return False
            if "auth_provider" in filters and u.get("auth_provider") != filters["auth_provider"]:
                return False
            if "status" in filters and u.get("status") != filters["status"]:
                return False
        return True

    matched = [u for u in users_rows if _matches(u)]

    key = sort.lstrip("-")
    desc = sort.startswith("-")

    def _sort_key(u):
        v = u.get(key)
        if key in ("created_at", "last_login_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if v is None:
            return ""
        return str(v)

    matched.sort(key=_sort_key, reverse=desc)

    start_idx = 0
    if cursor is not None:
        # Cursor is opaque in vendor schema; here it is the last seen user id.
        # Start after the row whose id == cursor; if not found, treat as empty page.
        try:
            idx = next(i for i, u in enumerate(matched) if isinstance(u, dict) and u.get("id") == cursor)
            start_idx = idx + 1
        except StopIteration:
            start_idx = len(matched)

    page = matched[start_idx:start_idx + limit]
    next_cursor = None
    if start_idx + limit < len(matched) and page:
        next_cursor = page[-1].get("id")

    def _public_user(u):
        return {
            "id": u.get("id"),
            "email": u.get("email"),
            "display_name": u.get("display_name"),
            "auth_provider": u.get("auth_provider"),
            "status": u.get("status"),
            "last_login_at": u.get("last_login_at"),
            "created_at": u.get("created_at"),
            "updated_at": u.get("updated_at"),
        }

    resp = {
        "object": "list",
        "data": [_public_user(u) for u in page],
        "total": len(matched),
        "limit": limit,
        "has_more": (start_idx + limit) < len(matched),
        "next_cursor": next_cursor,
        "sort": sort,
        "rate_limit": rl,
        "auth": {
            "user_id": user.get("id"),
            "session_id": sess.get("id"),
        }
    }
    _log(200, access_token, None, {"rate_limit": rl})
    return resp

def Optional_Settings__get_user(access_token, user_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0292000" if __import__("os").path.isdir("./environment_mix/0292000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str):
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _find_usage_file():
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return "request_logs.json"

    def _rate_meta(rows, credential):
        # Simple rolling window limiter (best-effort; only standard library + unknown vendor policy)
        limit_n = 120
        window_s = 60
        now = _now()
        used = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                used += 1
        return {"limit": limit_n, "window_seconds": window_s, "used": used}

    def _log(endpoint, http_status, credential, error_code=None, meta=None):
        fname = _find_usage_file()
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        now = _now()
        row = {
            "id": f"inb_req_{int(time.time() * 1000)}",
            "endpoint": endpoint,
            "credential": credential,
            "status": int(http_status),
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": now.isoformat().replace("+00:00", "Z"),
        }
        if meta:
            row["meta"] = meta
        rows.append(row)
        _save(fname, rows)

    endpoint = "Optional Settings: get_user"
    credential = access_token

    # Validate inputs (allow real datastore ids; schema pattern uses ULID base32, but data may not strictly comply)
    if not isinstance(access_token, str) or not access_token.strip():
        meta = {"field": "access_token"}
        _log(endpoint, 400, credential, "VALIDATION_ERROR", meta)
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string", field="access_token")
    if not isinstance(user_id, str) or not user_id.strip():
        meta = {"field": "user_id"}
        _log(endpoint, 400, credential, "VALIDATION_ERROR", meta)
        return _err("VALIDATION_ERROR", "user_id must be a non-empty string", field="user_id")
    # Soft validation: only reject clearly wrong prefix; don't reject existing ids due to overly strict regex.
    if not user_id.startswith("inb_usr_"):
        meta = {"field": "user_id"}
        _log(endpoint, 400, credential, "VALIDATION_ERROR", meta)
        return _err("VALIDATION_ERROR", "user_id must start with 'inb_usr_'", field="user_id")

    # Rate limit check (log after decision; but need existing logs to compute)
    usage_file = _find_usage_file()
    usage_rows = _load(usage_file)
    if not isinstance(usage_rows, list):
        usage_rows = []
    rm = _rate_meta(usage_rows, credential)
    if rm["used"] >= rm["limit"]:
        _log(endpoint, 429, credential, "RATE_LIMIT", {"rate_limit": rm})
        return _err("RATE_LIMIT", "Rate limit exceeded", rate_limit=rm)

    # Authenticate: access_token is provided and should match stored session access_token_hash directly
    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    now = _now()
    authed_session = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("access_token_hash") != access_token:
            continue
        if s.get("status") != "active":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if not exp or exp <= now:
            continue
        authed_session = s
        break

    if not authed_session:
        _log(endpoint, 401, credential, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or expired session")

    # Update last_seen_at on use (observable dynamics)
    updated_sessions = False
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == authed_session.get("id"):
            s["last_seen_at"] = now.isoformat().replace("+00:00", "Z")
            s["updated_at"] = now.isoformat().replace("+00:00", "Z")
            updated_sessions = True
            break
    if updated_sessions:
        _save("sessions.json", sessions)

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    target = None
    for u in users:
        if isinstance(u, dict) and u.get("id") == user_id:
            target = u
            break

    if not target:
        _log(endpoint, 404, credential, "NOT_FOUND")
        return _err("NOT_FOUND", "User not found")

    # Visibility: caller can fetch itself; otherwise require admin/owner on at least one server AND target not deleted?
    caller_user_id = authed_session.get("user_id")
    if user_id != caller_user_id:
        # Check if caller has elevated role anywhere (best available rule; schema doesn't include global admin)
        sacc = _load("server_access.json")
        if not isinstance(sacc, list):
            sacc = []
        elevated = False
        for g in sacc:
            if not isinstance(g, dict):
                continue
            if g.get("user_id") != caller_user_id:
                continue
            if g.get("status") != "active":
                continue
            if g.get("role") in ("owner", "admin"):
                elevated = True
                break
        if not elevated:
            _log(endpoint, 404, credential, "NOT_FOUND")
            return _err("NOT_FOUND", "User not found")

    # Do not expose password_hash
    out = dict(target)
    if "password_hash" in out:
        out["password_hash"] = None

    _log(endpoint, 200, credential)
    return {"user": out}

