        return _err("UNAUTHORIZED", "Invalid or expired session")

    # permission: self or elevated (owner/admin somewhere)
    caller_user_id = authed_session.get("user_id")
    elevated = False
    if caller_user_id != user_id:
        sacc = _load("server_access.json")
        if not isinstance(sacc, list):
            sacc = []
        for g in sacc:
            if not isinstance(g, dict):
                continue
            if g.get("user_id") != caller_user_id:
                continue
            if g.get("status") != "active":
                continue
            if g.get("role") in ("owner", "admin"):
                elevated = True
                break
        if not elevated:
            _log(endpoint, 401, credential, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Caller lacks permission to disable this user")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    idx = None
    for i, u in enumerate(users):
        if isinstance(u, dict) and u.get("id") == user_id:
            idx = i
            break
    if idx is None:
        _log(endpoint, 404, credential, "NOT_FOUND")
        return _err("NOT_FOUND", "User not found")

    cur = users[idx].get("status")
    if cur != "active":
        _log(endpoint, 409, credential, "INVALID_TRANSITION", {"from": cur, "to": "disabled"})
        return _err("INVALID_TRANSITION", "User can only be disabled from status='active'", from_status=cur, to_status="disabled")

    users[idx]["status"] = "disabled"
    users[idx]["updated_at"] = now.isoformat().replace("+00:00", "Z")
    _save("users.json", users)

    # revoke active sessions for this user (security best practice; not explicitly required but consistent)
    changed = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("user_id") != user_id:
            continue
        if s.get("status") == "active":
            s["status"] = "revoked"
            s["updated_at"] = now.isoformat().replace("+00:00", "Z")
            changed = True
    if changed:
        _save("sessions.json", sessions)

    _log(endpoint, 200, credential)
    out = dict(users[idx])
    if "password_hash" in out:
        out["password_hash"] = None
    return {"user": out}

