def Optional_Settings__get_auth_context(access_token, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0292000" if __import__("os").path.isdir("./environment_mix/0292000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")
    def _parse_dt(x):
        if x is None: return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str): return None
        s = x.strip()
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _find_usage_file():
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return "request_logs.json"

    def _rate_meta(rows, credential):
        limit_n = 120
        window_s = 60
        now = _now()
        used = 0
        for r in rows:
            if not isinstance(r, dict): 
                continue
            if r.get("credential") != credential:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                used += 1
        return {"limit": limit_n, "window_seconds": window_s, "used": used}

    def _log(http_status, credential, error_code=None, meta=None):
        fname = _find_usage_file()
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": f"inb_req_{int(time.time()*1000)}",
            "endpoint": "Optional Settings: get_auth_context",
            "credential": credential,
            "status": http_status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now()),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        rows.append(row)
        _save(fname, rows)

    # validate access_token
    if not isinstance(access_token, str) or not access_token.strip():
        _log(400, access_token, "VALIDATION_ERROR", {"field": "access_token"})
        return _err("VALIDATION_ERROR", "Invalid access_token", field="access_token")

    token = access_token.strip()
    sessions = _load("sessions.json")
    users = _load("users.json")
    servers = _load("servers.json")
    sacc = _load("server_access.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(users, list): users = []
    if not isinstance(servers, list): servers = []
    if not isinstance(sacc, list): sacc = []

    now = _now()

    # locate session by id or client-visible access_token_hash value; allow hashed raw token fallback
    candidates = []
    for s in sessions:
        if not isinstance(s, dict): 
            continue
        if s.get("id") == token or s.get("access_token_hash") == token:
            candidates.append(s)
    if not candidates:
        h = hashlib.sha256(token.encode("utf-8")).hexdigest()
        alt = f"sha256${h}"
        for s in sessions:
            if not isinstance(s, dict): 
                continue
            if s.get("access_token_hash") in (h, alt):
                candidates.append(s)

    # choose an actually valid session and active user
    active_pair = None
    for s in candidates:
        if s.get("status") != "active":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if not exp or exp <= now:
            continue
        u = next((x for x in users if isinstance(x, dict) and x.get("id") == s.get("user_id")), None)
        if not u:
            continue
        if u.get("status") != "active":
            continue
        active_pair = (u, s)
        break

    fname = _find_usage_file()
    rrows = _load(fname)
    if not isinstance(rrows, list): rrows = []
    rl = _rate_meta(rrows, access_token)
    if rl["used"] >= rl["limit"]:
        _log(429, access_token, "RATE_LIMIT", {"rate_limit": rl})
        return _err("RATE_LIMIT", "Rate limit exceeded", rate_limit=rl)

    if not active_pair:
        _log(401, access_token, "UNAUTHORIZED", {"rate_limit": rl})
        return _err("UNAUTHORIZED", "Invalid, revoked, or expired session", rate_limit=rl)

    u, s = active_pair

    # update session last_seen_at
    updated = False
    for i, row in enumerate(sessions):
        if isinstance(row, dict) and row.get("id") == s.get("id"):
            sessions[i] = dict(row)
            sessions[i]["last_seen_at"] = _iso(now)
            sessions[i]["updated_at"] = _iso(now)
            updated = True
            break
    if updated:
        _save("sessions.json", sessions)

    # roles/grants summary
    grants = [g for g in sacc if isinstance(g, dict) and g.get("user_id") == u.get("id") and g.get("status") == "active"]
    roles_by_server = {}
    for g in grants:
        sid = g.get("server_id")
        role = g.get("role")
        if sid and role:
            roles_by_server[sid] = role

    # include server names for convenience
    server_name = {sv.get("id"): sv.get("name") for sv in servers if isinstance(sv, dict)}
    roles = [{"server_id": sid, "server_name": server_name.get(sid), "role": role} for sid, role in roles_by_server.items()]

    resp = {
        "user": {
            "id": u.get("id"),
            "email": u.get("email"),
            "display_name": u.get("display_name"),
            "auth_provider": u.get("auth_provider"),
            "status": u.get("status"),
            "last_login_at": u.get("last_login_at"),
            "created_at": u.get("created_at"),
            "updated_at": u.get("updated_at"),
        },
        "session": {
            "id": s.get("id"),
            "user_id": s.get("user_id"),
            "status": s.get("status"),
            "issued_at": s.get("issued_at"),
            "expires_at": s.get("expires_at"),
            "last_seen_at": _iso(now) if updated else s.get("last_seen_at"),
            "ip_address": s.get("ip_address"),
            "user_agent": s.get("user_agent"),
            "created_at": s.get("created_at"),
            "updated_at": _iso(now) if updated else s.get("updated_at"),
        },
        "roles": roles,
        "rate_limit": rl,
    }
    _log(200, access_token, None, {"rate_limit": rl, "roles_count": len(roles)})
    return resp
